import * as M from './model.js?v=9.0.0';
import {LAND_REGIONS} from './content.js?v=9.0.0';
import {COUNTRIES,FLAG_COST,flagImages} from './flags.js?v=9.0.0';
import {heroPortrait} from './portraits.js?v=9.0.0';
import {escapeHtml as esc} from './features.js?v=9.0.0';
const icon=n=>`<i data-lucide="${n}"></i>`;
const fmt=n=>Math.ceil(n).toLocaleString('en-US');
export function remainingText(ms){const t=Math.max(0,Math.ceil(ms/1000));return t>=3600?`${Math.floor(t/3600)}h ${Math.ceil(t%3600/60)}m`:t>=60?`${Math.floor(t/60)}m ${t%60}s`:`${t}s`;}
export function workItems(s,now=Date.now()){
 const items=[];
 for(const b of s.buildings)if(b.finishAt>now){const duration=(b.constructing?M.TYPES[b.type].time:M.upgradeCost(b).time)*1000,start=b.startedAt??b.finishAt-duration;items.push({id:b.id,kind:'building',type:b.type,name:M.TYPES[b.type].name,x:b.x,z:b.z,height:b.type==='hall'?5.3:b.type==='tower'?5:3.6,finishAt:b.finishAt,remaining:b.finishAt-now,progress:Math.max(0,Math.min(1,(now-start)/Math.max(1,b.finishAt-start))),gems:M.skipCost(b.finishAt,now),level:b.level,constructing:!!b.constructing});}
 for(const [id,h] of Object.entries(s.heroes||{}))if(h.finishAt>now){const duration=(id==='machine'?20+h.level*8:M.heroCost(h).time)*1000,start=h.startedAt??h.finishAt-duration;items.push({id,kind:'hero',type:id,name:M.HEROES[id].name,finishAt:h.finishAt,remaining:h.finishAt-now,progress:Math.max(0,Math.min(1,(now-start)/Math.max(1,h.finishAt-start))),gems:M.skipCost(h.finishAt,now),level:h.level});}
 return items;
}
export class VillageUI{
 constructor(b){this.b=b;this.nodes=new Map();this.overlay=document.createElement('div');this.overlay.className='village-overlays';document.getElementById('app').append(this.overlay);this.activeWork=null;
  document.addEventListener('click',e=>{const el=e.target.closest('[data-village]');if(el&&!el.disabled){e.stopPropagation();this.handle(el).catch(err=>b.toast(err.message,true));}});
  document.addEventListener('input',e=>{if(e.target.id==='flag-search')this.filterFlags(e.target.value);if(e.target.matches('[data-detail-control]'))this.renderDetail();});
 }
 show(kind,title,body){this.b.showModal('village-'+kind,this.b.header('EMBERFALL',title)+`<div class="modal-body">${body}</div>`);}
 sync(){const s=this.b.village(),battle=this.b.battle();this.items=battle?[]:workItems(s);const keys=new Set(this.items.map(w=>w.kind+':'+w.id));
  for(const [key,node] of this.nodes)if(!keys.has(key)){node.remove();this.nodes.delete(key);}
  for(const w of this.items){const key=w.kind+':'+w.id;let node=this.nodes.get(key);if(!node){node=document.createElement('button');node.className='world-work';node.dataset.village='work';node.dataset.kind=w.kind;node.dataset.id=w.id;node.innerHTML='<span class="world-work-name"></span><span class="world-work-time"></span><span class="world-work-track"><span></span></span>';this.nodes.set(key,node);this.overlay.append(node);}node.title=w.name+' · '+remainingText(w.remaining)+' · '+w.gems+' gems to finish';node.setAttribute('aria-label',node.title);node.querySelector('.world-work-name').textContent=w.name;node.querySelector('.world-work-time').textContent=remainingText(w.remaining)+' · ◆ '+w.gems;node.querySelector('.world-work-track>span').style.width=(w.progress*100)+'%';}
  this.position();
  if(this.activeWork&&this.b.modalKind()==='village-work'){const w=this.items.find(w=>w.id===this.activeWork.id&&w.kind===this.activeWork.kind),label=document.getElementById('work-remaining'),button=document.getElementById('work-finish');if(w){label.textContent=remainingText(w.remaining);document.getElementById('work-progress').style.width=w.progress*100+'%';button.textContent='Finish now · '+w.gems+' gems';button.disabled=this.b.root().gems<w.gems;}else{label.textContent='Completed';button.textContent='Completed';button.disabled=true;}}
 }
 position(){for(const w of this.items||[]){const node=this.nodes.get(w.kind+':'+w.id);let position={...w,height:(this.b.world.buildingMap?.get(w.id)?.userData.visualHeight||w.height)+.4};if(w.kind==='hero'){const hero=this.b.world.heroVisitors?.children.find(m=>m.userData.heroType===w.id);if(!hero){node.hidden=true;continue;}position={x:hero.position.x,z:hero.position.z,height:2.8};}const p=this.b.world.projectPoint(position.x,position.height,position.z);node.hidden=p.x<30||p.x>this.b.world.container.clientWidth-30||p.y<40||p.y>this.b.world.container.clientHeight-20||!!this.b.battle()||this.b.placing();if(!node.hidden)node.style.transform=`translate(${p.x}px,${p.y}px) translate(-50%,-100%)`;}}
 work(kind,id){const w=workItems(this.b.village()).find(w=>w.kind===kind&&w.id===id);if(!w){this.b.toast('This upgrade has already finished.');return;}this.activeWork={kind,id,realm:this.b.realm()};this.show('work',w.name+' upgrade',`${kind==='hero'?heroPortrait(id,'work-portrait',Math.max(1,w.level)):''}<p class="work-level">${w.constructing?'Construction · Level '+w.level:'Level '+w.level+' → '+(w.level+1)}</p><strong class="work-countdown" id="work-remaining">${remainingText(w.remaining)}</strong><div class="work-progress-track"><span id="work-progress" style="width:${w.progress*100}%"></span></div><p class="modal-intro">Your upgrade continues while you are away. Spend gems to finish immediately.</p><button class="btn btn-gold btn-full" id="work-finish" data-village="finish" ${this.b.root().gems<w.gems?'disabled':''}>Finish now · ${w.gems} gems</button><p class="wallet-total">${icon('gem')} ${fmt(this.b.root().gems)} gems available</p>`);}
 land(){const s=this.b.village(),level=M.hallLevel(s);this.show('land','Across the bridge',`<p class="modal-intro">Town Hall ${level} / 15 · New land opens automatically when the Town Hall upgrade completes.</p><div class="land-list">${LAND_REGIONS.map(r=>`<button class="land-card ${level>=r.unlock?'unlocked':'locked'}" data-village="visit-land" data-id="${r.id}"><span>${icon(level>=r.unlock?'trees':'lock-keyhole')}</span><strong>${r.name}</strong><small>${level>=r.unlock?'Open for construction':'Unlock at Town Hall '+r.unlock}</small><b>${r.x2-r.x1} × ${r.z2-r.z1} tiles</b></button>`).join('')}</div><p class="guide-foot">Select a region to move the camera there. The river and bridge stay clear for travel.</p>`);}
 async flags(){this.show('flags','Country flags',`<p class="modal-intro">${COUNTRIES.length} country and territory flags · ${FLAG_COST} gold each. Choose a flag, then place its pole on an open tile.</p><label class="flag-search">Search country<input id="flag-search" type="search" placeholder="Myanmar, Thailand, Japan…" autocomplete="off"></label><div class="flag-gallery" id="flag-gallery"></div>`);this.flagData=await flagImages();if(this.b.modalKind()==='village-flags')this.filterFlags('');}
 filterFlags(query){const grid=document.getElementById('flag-gallery');if(!grid||!this.flagData)return;const term=query.trim().toLowerCase();const countries=COUNTRIES.filter(c=>(c.name+' '+c.code+' '+c.continent).toLowerCase().includes(term));grid.innerHTML=countries.map(c=>`<button class="flag-card" data-village="place-flag" data-code="${c.code}" ${this.b.root().gold<FLAG_COST?'disabled':''}><img src="${this.flagData[c.code]}" alt="${esc(c.name)} flag" width="160" height="120" loading="lazy"><strong>${esc(c.name)}</strong><small>${FLAG_COST} gold</small></button>`).join('')||'<p>No matching flags.</p>';}
 detail(kind,type,level){this.detailState={kind,type,level};const name=kind==='hero'?M.HEROES[type].name:kind==='troop'?M.TROOPS[type].name:M.TYPES[type].name;this.show('detail',name+' · 3D view',`<div class="model-inspector"><canvas id="detail-canvas" width="640" height="540" aria-label="${esc(name)} rotatable 3D model"></canvas><div class="detail-controls"><label>Rotate<input data-detail-control id="detail-angle" type="range" min="-180" max="180" value="25"></label><label>View level <output id="detail-level-label">${level}</output><input data-detail-control id="detail-level" type="range" min="1" max="${kind==='hero'?50:15}" value="${level}"></label><p>Model preview · Changing the preview level does not upgrade your village.</p></div></div>`);this.renderDetail();}
 renderDetail(){const canvas=document.getElementById('detail-canvas');if(!canvas)return;const level=Number(document.getElementById('detail-level').value);document.getElementById('detail-level-label').textContent=level;this.b.world.paintDetail(canvas,{...this.detailState,level},Number(document.getElementById('detail-angle').value)*Math.PI/180);}
 async handle(el){const a=el.dataset.village;el.disabled=true;try{
  if(a==='work')this.work(el.dataset.kind,el.dataset.id);
  else if(a==='finish'){if(!this.activeWork)return;await this.b.mutate({type:'skip',kind:this.activeWork.kind,id:this.activeWork.id,realm:this.activeWork.realm});this.b.toast('Upgrade completed.');this.b.closeModal();this.sync();}
  else if(a==='land')this.land();
  else if(a==='visit-land'){const r=LAND_REGIONS.find(r=>r.id===el.dataset.id);this.b.closeModal();this.b.world.focusAt((r.x1+r.x2)/2,(r.z1+r.z2)/2,1.5);if(M.hallLevel(this.b.root())<r.unlock)this.b.toast(r.name+' opens at Town Hall '+r.unlock+'.');}
  else if(a==='flags')await this.flags();
  else if(a==='place-flag')this.b.startFlag(el.dataset.code);
  else if(a==='move-flag')this.b.startFlag(el.dataset.code,el.dataset.id);
  else if(a==='detail')this.detail(el.dataset.kind,el.dataset.type,Number(el.dataset.level)||1);
 }finally{if(el.isConnected)el.disabled=false;}}
 flagSelected(id){const f=this.b.village().flags?.find(f=>f.id===id);if(!f)return;const name=COUNTRIES.find(c=>c.code===f.code)?.name||f.code;this.show('flag-selected',name+' flag',`<p class="modal-intro">Move your flag to another empty tile.</p><button class="btn btn-gold" data-village="move-flag" data-code="${f.code}" data-id="${f.id}">Move flag</button>`);}
}
